#ifdef __cplusplus
extern "C"
{
#endif

#include "syscall.h"
#include "ae350.h"

#include <stdint.h>
#include <stdio.h>

#define SYSCALL_TABLE_SIZE 2012
#ifdef PLIC_BASE
#define TARGET0_PLIC_CLAIM_COMP (PLIC_BASE + 0x200004)
#else
#define TARGET0_PLIC_CLAIM_COMP 0
#endif
#define MCAUSE_INT_EXPCODE_MASK (0x1FF)

#define PRINT_ERROR(format, ...) \
  printf("\033[31m[ERROR] " format "\033[0m", ##__VA_ARGS__)

#define WRITE_ERROR(format, ...) do { \
  char buf[100]; \
  int len = sprintf(buf, "\033[31m[ERROR] " format "\033[0m\n", ##__VA_ARGS__); \
  _write(2, buf, len); \
} while(0)


__attribute__((used, noreturn)) void _exit(int exit_status);

typedef long (*syscall_t)(long, long, long, long, long, long, long);

static void* syscall_table[SYSCALL_TABLE_SIZE];

__attribute__((constructor))
static void init_syscall_table(void) {
  syscall_table[SYS_open]         = (void*)_open;
  syscall_table[SYS_write]        = (void*)_write;
  syscall_table[SYS_getcwd]       = (void*)_getcwd;
  syscall_table[SYS_lseek]        = (void*)_lseek;
  syscall_table[SYS_read]         = (void*)_read;
  syscall_table[SYS_close]        = (void*)_close;
  syscall_table[SYS_gettimeofday] = (void*)_gettimeofday;
  syscall_table[SYS_access]       = (void*)_access;
  syscall_table[SYS_faccessat]    = (void*)_faccessat;
  syscall_table[SYS_fstat]        = (void*)_fstat;
  syscall_table[SYS_fstatat]      = (void*)_fstatat;
  syscall_table[SYS_link]         = (void*)_link;
  syscall_table[SYS_lstat]        = (void*)_lstat;
  syscall_table[SYS_stat]         = (void*)_stat;
  syscall_table[SYS_openat]       = (void*)_openat;
  syscall_table[SYS_rename]       = (void*)_rename;
  syscall_table[SYS_unlink]       = (void*)_unlink;
}


// strong symbol overrides the weak one in bsp
long syscall_handler(long n, long a0, long a1, long a2, long a3, long a4, long a5)
{
  syscall_t f = (syscall_t) syscall_table[n];
  return f(a0, a1, a2, a3, a4, a5, n);
}

// strong symbol overrides the weak one in bsp
long except_handler(long cause, long epc)
{
  uint64_t mdcause, mtval;

  asm volatile("csrr %0, mdcause" : "=r"(mdcause));
  asm volatile("csrr %0, mtval" : "=r"(mtval));

  WRITE_ERROR("Trap occurred!");
  WRITE_ERROR("mcause: 0x%lx", cause);
  WRITE_ERROR("mdcause: 0x%lx", mdcause);
  WRITE_ERROR("mepc: 0x%lx", epc);
  WRITE_ERROR("mtval: 0x%lx", mtval);

  _exit(cause); // notify VSIM about the exception

  return epc;
}

#ifdef __cplusplus
}
#endif

#ifndef HTIF_H
#define HTIF_H

#include <stddef.h>
#include <stdint.h>

// L1 Cache Control Commands
#define CCTL_L1D_WBINVAL_ALL 6
#define CCTL_L1D_WB_ALL      7
#define CCTL_L1D_INVAL_ALL   23

// L2 Cache Control and Status Constants
#define CCTL_L2_WBINVAL_ALL  0x12
#define CCTL_L2_ST_RUNNING   1
#define CCTL_ST_MASK         0xF

// L2 Cache Control Register Addresses
#define L2C_REG_CTL          0xe0500008
#define L2C_REG_CCTL         0xe0500040
#define L2C_REG_CCTL_M0_ST   0xe0500080
#define TOHOST_CMD_REG       0xe0080010

uint64_t magicmem[8] __attribute__((aligned(64)));

#if __riscv_xlen == 64
#define TOHOST_CMD(dev, cmd, payload) \
  (((uint64_t)(dev) << 56) | ((uint64_t)(cmd) << 48) | (uint64_t)(payload))
#define REG_T uint64_t
#else
#define TOHOST_CMD(dev, cmd, payload) \
  ({ \
    if ((dev) || (cmd)) \
      __builtin_trap(); \
    (payload); \
  })
#define REG_T uint32_t
#endif

static inline void flush_all_dcache(void)
{
  // L1 DCache writeback and invalidate all
  asm volatile("csrw mcctlcommand, %0" :: "rK"(CCTL_L1D_WBINVAL_ALL));

#if __riscv_xlen == 64
  // Check for L2 cache and flush it if available
  asm volatile(
    "csrr    t0, mmsc_cfg\n"
    "li      t1, 1\n"
    "slli    t1, t1, 46\n"
    "and     t2, t0, t1\n"
    "beqz    t2, 1f\n"
    "li      t3, 0xe0500008\n"
    "ld      t4, 0(t3)\n"
    "andi    t4, t4, 1\n"
    "beqz    t4, 1f\n"
    "li      t5, 0xe0500040\n"
    "li      t6, %[cmd]\n"
    "sd      t6, 0(t5)\n"
    "2:\n"
    "li      t2, 0xe0500080\n"
    "ld      t3, 0(t2)\n"
    "li      t4, %[mask]\n"
    "and     t3, t3, t4\n"
    "li      t5, %[running]\n"
    "beq     t3, t5, 2b\n"
    "1:\n"
    :
    : [cmd] "K"(CCTL_L2_WBINVAL_ALL),
      [mask] "K"(CCTL_ST_MASK),
      [running] "K"(CCTL_L2_ST_RUNNING)
  );
#endif
}

__attribute__((used)) static inline void sim_syscall(uint64_t dev,
                                                       uint64_t cmd,
                                                       uint64_t tohost)
{
  volatile uint64_t* command = (volatile uint64_t*) TOHOST_CMD_REG;
  uint64_t tohost_cmd = TOHOST_CMD(dev, cmd, tohost);
  flush_all_dcache();
  *command = tohost_cmd;
  asm volatile("fence rw,rw");
}

__attribute__((used)) static inline uint64_t frontend_syscall(uint64_t n,
                                                               uint64_t a0,
                                                               uint64_t a1,
                                                               uint64_t a2,
                                                               uint64_t a3,
                                                               uint64_t a4,
                                                               uint64_t a5,
                                                               uint64_t a6)
{
  magicmem[0] = n;
  magicmem[1] = a0;
  magicmem[2] = a1;
  magicmem[3] = a2;
  magicmem[4] = a3;
  magicmem[5] = a4;
  magicmem[6] = a5;
  magicmem[7] = a6;
  sim_syscall(0, 0, (uintptr_t) magicmem);
  return magicmem[0];
}

#endif // HTIF_H

