#include <riscv_vector.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

#include "core_v5.h"
#include "hvm_util.h"
#include "include/ace_user.h"

unsigned long long rdcycle() {
  unsigned long long result;
  asm volatile("csrr %0, mcycle" : "=r"(result));
  return result;
}

#define HVM

#ifdef HVM
#define MALLOC malloc_hvm
#define FREE free_hvm
#else
#define MALLOC malloc
#define FREE free
#endif

// Convenient macro for clobbering all vector registers
#define CLOBBER_ALL_VREGS \
  "v0", "v1", "v2", "v3", "v4", "v5", "v6", "v7", \
  "v8", "v9", "v10", "v11", "v12", "v13", "v14", "v15", \
  "v16", "v17", "v18", "v19", "v20", "v21", "v22", "v23", \
  "v24", "v25", "v26", "v27", "v28", "v29", "v30", "v31"

void acervv_abs_diff_stripmine_m2(int16_t* array, int16_t scalar, uint16_t* result,
                     size_t length) {
  // Strip mining loop
  for (size_t i = 0; i < length;) {
    size_t vl = __riscv_ace_vsetvl_e16m2(length - i);
    vint16m2_t vs = __riscv_vle16_v_i16m2(&array[i], vl);
    vuint16m2_t res = ace_vabd_vx_u16m2(vs, scalar, vl);
    __riscv_vse16_v_u16m2(&result[i], res, vl);
    i += vl;
  }
}

void acervv_abs_diff_stripmine_m8(int16_t* array, int16_t scalar, uint16_t* result,
                     size_t length) {
  // Strip mining loop
  for (size_t i = 0; i < length;) {
    size_t vl = __riscv_ace_vsetvl_e16m8(length - i);
    vint16m8_t vs = __riscv_vle16_v_i16m8(&array[i], vl);
    vuint16m8_t res = ace_vabd_vx_u16m8(vs, scalar, vl);
    __riscv_vse16_v_u16m8(&result[i], res, vl);
    i += vl;
  }
}

// fixed for length = 512
void acervv_abs_diff_unroll_m2(int16_t* array, int16_t scalar, uint16_t* result, size_t length) {
  size_t vl = __riscv_ace_vsetvlmax_e16m2();

  asm volatile(
    "vle16.v v0, (%0)\n"
    "vle16.v v2, (%1)\n"
    "vle16.v v4, (%2)\n"
    "vle16.v v6, (%3)\n"
    "vle16.v v8, (%4)\n"
    "vle16.v v10, (%5)\n"
    "vle16.v v12, (%6)\n"
    "vle16.v v14, (%7)\n"
    "vabd_vx v16, v0, %10, 1\n"
    "vabd_vx v18, v2, %10, 1\n"
    "vabd_vx v20, v4, %10, 1\n"
    "vabd_vx v22, v6, %10, 1\n"
    "vabd_vx v24, v8, %10, 1\n"
    "vabd_vx v26, v10, %10, 1\n"
    "vabd_vx v28, v12, %10, 1\n"
    "vabd_vx v30, v14, %10, 1\n"
    "vse16.v v16, (%8)\n"
    "vse16.v v18, (%9)\n"
    "vse16.v v20, (%11)\n"
    "vse16.v v22, (%12)\n"
    "vse16.v v24, (%13)\n"
    "vse16.v v26, (%14)\n"
    "vse16.v v28, (%15)\n"
    "vse16.v v30, (%16)\n"
    :
    : "r"(array), "r"(array + vl), "r"(array + 2*vl), "r"(array + 3*vl),
      "r"(array + 4*vl), "r"(array + 5*vl), "r"(array + 6*vl), "r"(array + 7*vl),
      "r"(result), "r"(result + vl), "r"(scalar),
      "r"(result + 2*vl), "r"(result + 3*vl), "r"(result + 4*vl),
      "r"(result + 5*vl), "r"(result + 6*vl), "r"(result + 7*vl)
    : "memory", CLOBBER_ALL_VREGS
  );
}

// fixed for length = 512
void acervv_abs_diff_unroll_m8(int16_t* array, int16_t scalar, uint16_t* result, size_t length) {
  size_t vl = __riscv_ace_vsetvlmax_e16m8();

  asm volatile(
    "vle16.v v0, (%0)\n"
    "vle16.v v8, (%1)\n"
    "vabd_vx v16, v0, %4, 1\n"
    "vabd_vx v24, v8, %4, 1\n"
    "vse16.v v16, (%2)\n"
    "vse16.v v24, (%3)\n"
    :
    : "r"(array), "r"(array + vl),
      "r"(result), "r"(result + vl),
      "r"(scalar)
    : "memory", CLOBBER_ALL_VREGS
  );
}

void (*acervv_abs_diff)(int16_t* array, int16_t scalar, uint16_t* result,
                     size_t length)
                    //  = acervv_abs_diff_stripmine_m2;
                    //  = acervv_abs_diff_stripmine_m8;
                     = acervv_abs_diff_unroll_m2;
                    //  = acervv_abs_diff_unroll_m8;


void rvv_abs_diff(int16_t* array, int16_t scalar, uint16_t* result,
                  size_t length) {
  // Strip mining loop
  for (size_t i = 0; i < length;) {
    size_t vl = __riscv_ace_vsetvl_e16m8(length - i);
    vint16m8_t vs = __riscv_vle16_v_i16m8(&array[i], vl);

    // Calculate max(vs, scalar) - min(vs, scalar) for absolute difference
    vint16m8_t max_val = __riscv_vmax_vx_i16m8(vs, scalar, vl);
    vint16m8_t min_val = __riscv_vmin_vx_i16m8(vs, scalar, vl);
    vint16m8_t abs_diff = __riscv_vsub_vv_i16m8(max_val, min_val, vl);

    // Convert to unsigned
    vuint16m8_t res = __riscv_vreinterpret_v_i16m8_u16m8(abs_diff);
    __riscv_vse16_v_u16m8(&result[i], res, vl);
    i += vl;
  }
}

void scalar_abs_diff(int16_t* array, int16_t scalar, uint16_t* result,
                     size_t length) {
  for (size_t i = 0; i < length; i++) {
    int32_t diff = (int32_t)array[i] - scalar;
    result[i] = (uint16_t)(diff >= 0 ? diff : -diff);
  }
}

void test_abs_diff() {
  printf("Testing absolute difference (ace_vabd_vx)\n");

  // Prepare test data
  size_t length = 512;
  int16_t scalar = 1000;
  int16_t* array = (int16_t*)MALLOC(length * sizeof(int16_t));

  // Fill array with random values
  for (size_t i = 0; i < length; i++) {
    array[i] = (int16_t)(rand() % 65536 - 32768);
  }

  // Allocate result arrays
  uint16_t* expected = (uint16_t*)MALLOC(length * sizeof(int16_t));
  uint16_t* acervv_result = (uint16_t*)MALLOC(length * sizeof(uint16_t));
  uint16_t* rvv_result = (uint16_t*)MALLOC(length * sizeof(uint16_t));

  // Perform scalar absolute difference
  unsigned long long scalar_cycle_begin = rdcycle();
  scalar_abs_diff(array, scalar, expected, length);
  asm __volatile__("fence rw, rw" ::: "memory");
  unsigned long long scalar_cycle_end = rdcycle();

  // Perform standard RVV absolute difference
  unsigned long long rvv_cycle_begin = rdcycle();
  rvv_abs_diff(array, scalar, rvv_result, length);
  asm __volatile__("fence rw, rw" ::: "memory");
  unsigned long long rvv_cycle_end = rdcycle();

  // Perform vectorized absolute difference (ACE)
  unsigned long long acervv_cycle_begin = rdcycle();
  acervv_abs_diff(array, scalar, acervv_result, length);
  asm __volatile__("fence rw, rw" ::: "memory");
  unsigned long long acervv_cycle_end = rdcycle();

  // Verify results
  for (size_t i = 0; i < length; i++) {
    if (acervv_result[i] != expected[i]) {
      printf("ACERVV FAIL at index %zu:\n", i);
      printf("  Got:      %u\n", acervv_result[i]);
      printf("  Expected: %u\n", expected[i]);
      printf("  Input:    %d\n", array[i]);
      printf("  Scalar:   %d\n", scalar);
      exit(1);
    }
    if (rvv_result[i] != expected[i]) {
      printf("RVV FAIL at index %zu:\n", i);
      printf("  Got:      %u\n", rvv_result[i]);
      printf("  Expected: %u\n", expected[i]);
      printf("  Input:    %d\n", array[i]);
      printf("  Scalar:   %d\n", scalar);
      exit(1);
    }
  }

  printf("PASS\n");

  // Print performance results
  printf("Scalar version cycles: %llu\n",
         scalar_cycle_end - scalar_cycle_begin);
  printf("RVV version cycles: %llu\n", rvv_cycle_end - rvv_cycle_begin);
  printf("ACERVV version cycles: %llu\n",
         acervv_cycle_end - acervv_cycle_begin);

  FREE(array);
  FREE(expected);
  FREE(acervv_result);
  FREE(rvv_result);
}

int main(int argc, char const* argv[]) {
  enable_ace();

  test_abs_diff();

  return 0;
}

