#include <riscv_vector.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

#include "core_v5.h"
#include "hvm_util.h"
#include "include/ace_user.h"

unsigned long long rdcycle() {
  unsigned long long result;
  asm volatile("csrr %0, mcycle" : "=r"(result));
  return result;
}

#define HVM

#ifdef HVM
#define MALLOC malloc_hvm
#define FREE free_hvm
#else
#define MALLOC malloc
#define FREE free
#endif


void test_vqwmacc() {
  printf("Testing vqwmacc (ace_vqwmacc_vv)\n");

  // Prepare test data
  size_t len = 16;
  int8_t* src1 = (int8_t*)MALLOC(len * sizeof(int8_t));
  int16_t* src2 = (int16_t*)MALLOC(len * sizeof(int16_t));
  int32_t* vec_result = (int32_t*)MALLOC(len * sizeof(int32_t));
  int32_t* ref_result = (int32_t*)MALLOC(len * sizeof(int32_t));

  // Initialize with random values
  for (size_t i = 0; i < len; i++) {
    src1[i] = (int8_t)(rand() % 256 - 128);
    src2[i] = (int16_t)(rand() % 65536 - 32768);
    vec_result[i] = (int32_t)rand();
    ref_result[i] = vec_result[i];
  }

  // Scalar reference implementation
  unsigned long long scalar_start = rdcycle();
  for (size_t i = 0; i < len; i++) {
    ref_result[i] += (int32_t)src2[i] * (int32_t)src1[i];
  }
  asm __volatile__("fence rw, rw" ::: "memory");
  unsigned long long scalar_end = rdcycle();

  // Vector ACE implementation
  unsigned long long vec_start = rdcycle();

  size_t vl = __riscv_ace_vsetvl_e8m2(len);
  vint8m2_t vsrc1 = __riscv_vle8_v_i8m2(src1, vl);
  vint16m4_t vsrc2 = __riscv_vle16_v_i16m4(src2, vl);
  vint32m8_t vacc = __riscv_vle32_v_i32m8(vec_result, vl);
  vacc = ace_vqwmacc_vv_i32m8(vacc, vsrc2, vsrc1, 1, vl);
  __riscv_vse32_v_i32m8(vec_result, vacc, vl);

  asm __volatile__("fence rw, rw" ::: "memory");
  unsigned long long vec_end = rdcycle();

  // Verify results
  for (size_t i = 0; i < len; i++) {
    if (vec_result[i] != ref_result[i]) {
      printf("FAIL at index %zu:\n", i);
      printf("  Vector:    %d\n", vec_result[i]);
      printf("  Reference: %d\n", ref_result[i]);
      exit(1);
    }
  }

  printf("PASS\n");

  // Performance report
  printf("Scalar cycles: %llu\n", scalar_end - scalar_start);
  printf("Vector cycles: %llu\n", vec_end - vec_start);

  FREE(src1);
  FREE(src2);
  FREE(ref_result);
  FREE(vec_result);
}

int main(int argc, char const* argv[]) {
  enable_ace();

  test_vqwmacc();

  return 0;
}

