/*
 * Atomic / AXI-exclusive smoke test for the bus exclusive monitor in
 * src/utils/axi_to_tlm_bridge.hpp.
 *
 * The target variable lives in plain main memory (DDR), so every atomic goes
 * out over the bus as an AXI exclusive (LR/SC) sequence — exactly the path
 * that used to live-lock before the bridge implemented an exclusive monitor.
 * If the monitor is wrong, T1 hangs on the first sc.w; if it is right, all
 * four tests PASS.
 *
 *   -march must include 'a'  (e.g. rv32imafd)
 *   variable must NOT be placed in ILM/DLM (those resolve AMOs internally)
 */
#include <stdio.h>
#include <stdint.h>

/* In plain main memory so atomics traverse the bus. volatile keeps the
 * accesses from being optimized away. */
static volatile uint32_t shared = 0;

/* One LR/SC pair. Returns the sc.w result: 0 = success, non-zero = failure. */
static inline uint32_t lr_then_sc(volatile uint32_t *p, uint32_t newval)
{
    uint32_t old, sc_fail;
    __asm__ volatile(
        "lr.w   %0, (%2)\n"      /* exclusive read  -> monitor arms reservation, EXOKAY */
        "sc.w   %1, %3, (%2)\n"  /* exclusive write -> hit: write + EXOKAY (sc == 0) */
        : "=&r"(old), "=&r"(sc_fail)
        : "r"(p), "r"(newval)
        : "memory");
    (void)old;
    return sc_fail;
}

int main(void)
{
    int pass = 1;

    /* T1: plain LR/SC must succeed (sc == 0) and commit the new value. */
    shared = 0x11111111;
    uint32_t sc1 = lr_then_sc(&shared, 0xAAAA5555);
    printf("[T1] LR/SC success: sc=%u  mem=0x%08x  -> %s\n",
           sc1, shared,
           (sc1 == 0 && shared == 0xAAAA5555) ? "PASS" : "FAIL");
    if (!(sc1 == 0 && shared == 0xAAAA5555)) pass = 0;

    /* T2: a normal store between LR and SC breaks the reservation, so the SC
     * must fail (sc != 0) AND must not overwrite memory. */
    shared = 0x22222222;
    uint32_t old2, sc2;
    __asm__ volatile(
        "lr.w   %0, (%2)\n"
        "sw     %3, 0(%2)\n"     /* normal store hits the reserved address */
        "sc.w   %1, %4, (%2)\n"  /* must fail, must not write */
        : "=&r"(old2), "=&r"(sc2)
        : "r"(&shared), "r"(0xDEAD0000), "r"(0xBEEF1111)
        : "memory");
    (void)old2;
    printf("[T2] SC after store-break: sc=%u  mem=0x%08x  -> %s\n",
           sc2, shared,
           (sc2 != 0 && shared == 0xDEAD0000) ? "PASS" : "FAIL");
    if (!(sc2 != 0 && shared == 0xDEAD0000)) pass = 0;

    /* T3: amoswap.w — the BIU exclusive read-modify-write path (the original
     * hang was on an amoor.w on this same path). */
    shared = 0x33333333;
    uint32_t amo_old;
    __asm__ volatile(
        "amoswap.w %0, %2, (%1)\n"
        : "=&r"(amo_old)
        : "r"(&shared), "r"(0xC0DE0001)
        : "memory");
    printf("[T3] amoswap.w: old=0x%08x  new=0x%08x  -> %s\n",
           amo_old, shared,
           (amo_old == 0x33333333 && shared == 0xC0DE0001) ? "PASS" : "FAIL");
    if (!(amo_old == 0x33333333 && shared == 0xC0DE0001)) pass = 0;

    /* T4: repeated amoadd.w must produce the correct value, not just "not hang". */
    shared = 100;
    for (int i = 0; i < 5; i++) {
        __asm__ volatile("amoadd.w x0, %1, (%0)\n"
                         :: "r"(&shared), "r"(7) : "memory");
    }
    printf("[T4] amoadd.w x5 of +7: mem=%u (expect 135)  -> %s\n",
           shared, (shared == 135) ? "PASS" : "FAIL");
    if (shared != 135) pass = 0;

    printf("\n==== RESULT: %s ====\n", pass ? "ALL PASS" : "SOME FAIL");
    return pass ? 0 : 1;
}

