/*
 * Hybrid simulation checkpoint demo.
 *
 * Exercises VSIM's hybrid (fast-functional + cycle-accurate) flow by writing
 * to both a global array and a stack-local array, then triggering a WFI as a
 * checkpoint marker partway through the loop. The WFI is the agreed handoff
 * point: the fast-functional engine runs up to it, state is snapshotted, and
 * the cycle-accurate engine resumes from there. After the loop, the program
 * prints both arrays so the post-checkpoint output can be diffed against a
 * pure run to confirm the handoff preserved memory and register state.
 */

#include <stdio.h>
#include "platform.h"

#define ANDES_HYBRIDSIM_BEGIN \
    asm volatile("hybridsim_begin: " ::: "memory");
#define ANDES_HYBRIDSIM_END \
    asm volatile("hybridsim_end: " ::: "memory");

unsigned long long rdcycle() {
  asm volatile("fence rw, rw" ::: "memory");
#if __riscv_xlen == 32
  unsigned int lo, hi, hi2;
  do {
    asm volatile("csrr %0, mcycleh" : "=r"(hi));
    asm volatile("csrr %0, mcycle"  : "=r"(lo));
    asm volatile("csrr %0, mcycleh" : "=r"(hi2));
  } while (hi != hi2);
  return ((unsigned long long)hi << 32) | lo;
#else
  unsigned long long result;
  asm volatile("csrr %0, mcycle" : "=r"(result));
  return result;
#endif
}

#define N 20
int global[N];

double result[N][N];

static void prepare_data(double A[N][N], double B[N][N]) {
  for (int i = 0; i < N; ++i) {
    for (int j = 0; j < N; ++j) {
      A[i][j] = (double)(i + j);
      B[i][j] = (double)(i - j);
    }
  }
}

static void mat_mul(double C[N][N], double A[N][N], double B[N][N]) {
  for (int i = 0; i < N; ++i) {
    for (int j = 0; j < N; ++j) {
      double sum = 0.0;
      for (int k = 0; k < N; ++k) {
        sum += A[i][k] * B[k][j];
      }
      C[i][j] = sum;
    }
  }
}

int main(void) {
  double A[N][N];
  double B[N][N];

  prepare_data(A, B);

ANDES_HYBRIDSIM_BEGIN
  unsigned long long cycle_begin = rdcycle();

  mat_mul(result, A, B);

  unsigned long long cycle_end = rdcycle();
  printf("cycles: %llu\n", cycle_end - cycle_begin);

ANDES_HYBRIDSIM_END

  for (int i = 0; i < N; ++i) {
    for (int j = 0; j < N; ++j) {
      printf("%d, %d, %.2f\n", i, j, result[i][j]);
    }
  }

  return 0;
}

/*
 * Hybrid simulation FP-register handoff test.
 *
 * Sets a double in an FP register before hybridsim_begin and consumes it
 * after, with inline asm constraints that prevent the compiler from
 * spilling to memory or constant-folding across the handoff. This
 * exercises the FPR snapshot/restore path: the cycle-accurate side must
 * recover k = 12.345 from the dumped FPR (via dump_ae350.gdb) and the
 * fadd.d below must produce 12.346.
 */

#include <stdio.h>
#include "platform.h"

#define ANDES_HYBRIDSIM_BEGIN \
    asm volatile("hybridsim_begin: " ::: "memory");
#define ANDES_HYBRIDSIM_END \
    asm volatile("hybridsim_end: " ::: "memory");

int main(void) {
  double k = 12.345;
  // Force k into an FP register and prevent constant-folding across the
  // handoff point, so the cycle-accurate side must read k from the FPR
  // snapshotted at hybridsim_begin.
  asm volatile("" : "+f"(k));

ANDES_HYBRIDSIM_BEGIN

  asm volatile("fadd.d %0, %0, %1" : "+f"(k) : "f"(0.001));
  printf("k: %f\n", k);

  return 0;
}

