#include <stdio.h>
#include <inttypes.h>
#include <stdint.h>
#include <stdlib.h>
#include "memory_map.h"
#include "core_v5.h"

#if __riscv_xlen == 64
	#define ROTATE_LEN 64
#else
	#define ROTATE_LEN 32
#endif

#ifndef NDS_MIN_ILM_SIZE
	#define NDS_MIN_ILM_SIZE 0x6000
#endif


typedef struct {
	long *base;
	long size;
	const char *name;
	const char *asm_label_prefix;
} memory_config_t;

long micm_cfg;
long milmb;
long ilm_size;
long mdcm_cfg;
long dlm_size;
long mdlmb;

void setup_ilm() {
	micm_cfg = read_csr(NDS_MICM_CFG);

	ilm_size = (0x200 << ((micm_cfg >> 15) & 0x1f)) / sizeof(long);
	if (ilm_size < (NDS_MIN_ILM_SIZE / sizeof(long))) {
		printf("Error: ILM size should be >= 24 KiB to run this test.\n");
		exit(1);
	}

	set_csr(NDS_MILMB, 0x1);
	milmb = read_csr(NDS_MILMB);

	if (((micm_cfg >> 21) & 0x3) != 0) {
		milmb |= 0x4;
		write_csr(NDS_MILMB, milmb);
	}
}

void setup_dlm() {
	mdcm_cfg = read_csr(NDS_MDCM_CFG);

	if (((mdcm_cfg >> 15) & 0x1f) != 0) {
		dlm_size = (0x200 << ((mdcm_cfg >> 15) & 0x1f)) / sizeof(long);
	} else {
		printf("Error: DLM size should be > 0 KiB to run this test.\n");
		exit(1);
	}

	set_csr(NDS_MDLMB, 0x1);
	mdlmb = read_csr(NDS_MDLMB);

	if (((mdcm_cfg >> 21) & 0x3) != 0) {
		mdlmb |= 0x4;
		write_csr(NDS_MDLMB, mdlmb);
	}
}

void setup() {
	setup_ilm();
	setup_dlm();
}

long rotr(long num) {
	return (num >> 1) | (num << (ROTATE_LEN - 1));
}

void wait_for_transfer() {
	for (int i = 0; i < 32; i++) {
		asm volatile("nop");
	}
}

void print_initial_memory_data(const memory_config_t *mem_config) {
	uintptr_t start = (uintptr_t)mem_config->base;
	uintptr_t end = start + 32;

	printf("First read - Initial %s data:\n", mem_config->name);
	for (uintptr_t addr = start; addr < end; addr += 4) {
		unsigned int data = *(unsigned int *)(uintptr_t)addr;
