}

void generic_memory_test_pattern1(const memory_config_t *mem_config, long data1) {
	long offset, golden, test;
	char write_label[32], read_label[32];

	snprintf(write_label, sizeof(write_label), "%s_write_1:", mem_config->asm_label_prefix);
	snprintf(read_label, sizeof(read_label), "%s_read_1:", mem_config->asm_label_prefix);

	asm volatile ("# Pattern 1 write");
	test = data1;
	for (offset = 1; offset < mem_config->size; offset = offset << 2) {
		test = rotr(test);
		*(mem_config->base + offset) = test;
	}

	asm volatile ("# Pattern 1 read");
	golden = data1;
	for (offset = 1; offset < mem_config->size; offset = offset << 2) {
		golden = rotr(golden);
		test = *(mem_config->base + offset);
		printf("%s Read 1 - offset: %ld, expected: 0x%lx, actual: 0x%lx\n", 
		       mem_config->name, offset, golden, test);
		if (golden != test) {
			printf("%s Test failed at offset %ld\n", mem_config->name, offset);
			exit(1);
		}
	}
}

void generic_memory_test_pattern2(const memory_config_t *mem_config, long data2) {
