	snprintf(write_label, sizeof(write_label), "%s_write_2:", mem_config->asm_label_prefix);
	snprintf(read_label, sizeof(read_label), "%s_read_2:", mem_config->asm_label_prefix);

	asm volatile ("# Pattern 2 write");
	test = data2;
	for (offset = (mem_config->size >> 1); offset > 0; offset = offset >> 2) {
		test = rotr(test);
		*(mem_config->base + offset) = test;
	}

