		if (golden != test) {
			printf("%s Test failed at offset %ld\n", mem_config->name, offset);
			exit(1);
		}
	}
}

void run_memory_tests(const memory_config_t *mem_config, long data1, long data2) {
	printf("=== %s Testing ===\n", mem_config->name);
	printf("%s Base address: 0x%lx\n", mem_config->name, (unsigned long)mem_config->base);
	printf("%s Size: %ld words\n", mem_config->name, mem_config->size);

	print_initial_memory_data(mem_config);

	printf("Running %s test pattern 1...\n", mem_config->name);
	generic_memory_test_pattern1(mem_config, data1);

	printf("Running %s test pattern 2...\n", mem_config->name);
	generic_memory_test_pattern2(mem_config, data2);

	printf("%s tests passed!\n\n", mem_config->name);
}

