	printf("Starting local memory test...\n");

	setup();

	memory_config_t ilm_config = {
		.base = (long*)(((milmb >> 10) << 10)),
		.size = ilm_size,
		.name = "ILM",
		.asm_label_prefix = "ilm"
	};

	memory_config_t dlm_config = {
		.base = (long*)(((mdlmb >> 10) << 10)),
