/*
 * UART demo - demonstrates basic UART driver usage on AE350 platform.
 *
 * This example initializes UART2, sends a greeting, echoes received
 * characters, and exercises uart_putc / uart_puts
 * uart_getc is not implemented in simulator, so can't demo it here.
 */

#include "ae350.h"
#include "uart.h"

/* DEV_UART2 is needed by the UART driver. */
#ifndef DEV_UART2
#define DEV_UART2  AE350_UART2
#endif

/* Simple integer-to-hex string (for demonstrating putc). */
static void uart_put_hex(unsigned long val)
{
	uart_puts("0x");
	for (int i = (sizeof(val) * 8) - 4; i >= 0; i -= 4) {
		unsigned nibble = (val >> i) & 0xf;
		uart_putc(nibble < 10 ? '0' + nibble : 'a' + nibble - 10);
	}
}

int main(void)
{
	/* Initialize UART at 38400 baud (default for AE350 FPGA). */
	uart_init(38400);

	/* 1. Basic string output */
	uart_puts("=== UART Demo ===\n");
	uart_puts("UART2 initialized at 38400 baud.\n");

	/* 2. Character-level output */
	uart_puts("Printing A-Z: ");
	for (char c = 'A'; c <= 'Z'; c++)
		uart_putc(c);
	uart_puts("\n");

	/* 3. Print hart ID in hex using putc */
	unsigned long hartid;
	__asm__ volatile("csrr %0, mhartid" : "=r"(hartid));
	uart_puts("Hart ID: ");
	uart_put_hex(hartid);
	uart_puts("\n");

	/* 4. Echo loop - receive a character and send it back */
	// uart_puts("Type characters to echo (press 'q' to quit):\n");
	// while (1) {
