/*
 * PLIC interrupt demo - triggers an external interrupt via sim_control's
 * INT_TRIGGER register (offset 0x20).
 *
 * Writing an IRQ bitmask to SIM_CONTROL_BASE + 0x20 sets the CPU's int_src
 * signal directly. Each bit corresponds to a PLIC source (bit 0 = source 1).
 * sim_control auto-clears the signal after 1 cycle.
 *
 * Flow:
 *   1. Enable PLIC source and machine external interrupts
 *   2. Write IRQ bitmask to INT_TRIGGER register
 *   3. sim_control pulses int_src for 1 cycle -> PLIC latches pending
 *   4. CPU takes the trap -> ISR runs
 */

#include <stdio.h>
#include "platform.h"

#define SIM_CONTROL_BASE      0xE0080000
#define INT_TRIGGER_REG       (*(volatile unsigned int *)(SIM_CONTROL_BASE + 0x20))

#define PLIC_SOURCE_ID        1   /* bit 0 of int_trigger -> PLIC source 1 */

static volatile int interrupt_fired = 0;

/* Override weak alias for PLIC source 1 (rtc_period_irq_handler in BSP) */
void rtc_period_irq_handler(void)
{
	printf("[ISR] PLIC external interrupt received!\n");
	interrupt_fired = 1;
}

int main(void)
{
	printf("=== PLIC Interrupt Demo ===\n");

	/* Configure PLIC: enable source 1 with priority 1, threshold 0 */
	__nds__plic_set_priority(PLIC_SOURCE_ID, 1);
	__nds__plic_enable_interrupt(PLIC_SOURCE_ID);
	__nds__plic_set_threshold(0);

	/* Enable machine external interrupts */
	set_csr(NDS_MIE, MIP_MEIP);
	set_csr(NDS_MSTATUS, MSTATUS_MIE);

	printf("Triggering PLIC source %d via INT_TRIGGER register...\n",
	       PLIC_SOURCE_ID);

	/* Set bit 0 -> triggers PLIC source 1 */
	INT_TRIGGER_REG = (1 << (PLIC_SOURCE_ID - 1));
	/* int_trigger is auto-cleared by sim_control after 1 cycle */

	/* By the time we reach here, the ISR has already executed */
	while (!interrupt_fired) {
		printf("Waiting for PLIC interrupt delivery...\n");
	};
	printf("Done.\n");

	return 0;
}

