#include "platform.h"

#define SIM_CONTROL_BASE      0xE0080000
#define INT_TRIGGER_REG       (*(volatile unsigned int *)(SIM_CONTROL_BASE + 0x20))

#define AIA_SOURCE_ID         1 // RTC

static volatile int interrupt_fired = 0;

static void dump_aia_state(void)
{
	unsigned int trig = __nds__aplic_get_trig(AIA_SOURCE_ID);
	unsigned int eidelivery = imsic_csr_read(IMSIC_EIDELIVERY);
	unsigned int eithreshold = imsic_csr_read(IMSIC_EITHRESHOLD);
	unsigned int eie0 = imsic_csr_read(IMSIC_EIE0);

	printf("[DBG] APLIC source %d trigger mode = 0x%x\n",
	       AIA_SOURCE_ID, trig);
	printf("[DBG] IMSIC EIDELIVERY = 0x%x, EITHRESHOLD = 0x%x, EIE0 = 0x%x\n",
	       eidelivery, eithreshold, eie0);
