7	void matrix_multiply_scalar(int32_t A[N][N], int32_t B[N][N], int32_t C[N][N]) {
8	    for (int i = 0; i < N; i++) {
9	        for (int j = 0; j < N; j++) {
10	            C[i][j] = 0;
11	            for (int k = 0; k < N; k++) {
12	                C[i][j] += A[i][k] * B[k][j];
13	            }
14	        }
15	    }
16	}
17	
18	void matrix_multiply_rvv(int32_t A[N][N], int32_t B[N][N], int32_t C[N][N]) {
19	    for (int i = 0; i < N; i++) {
20	        for (int j = 0; j < N; j++) {
21	            C[i][j] = 0;
22	            size_t vl = __riscv_vsetvl_e32m1(N);
23	            vint32m1_t va = __riscv_vle32_v_i32m1(&A[i][0], vl);
24	            
25	            int32_t B_col[N];
26	            for (int k = 0; k < N; k++) {
27	                B_col[k] = B[k][j];
28	            }
29	            vint32m1_t vb = __riscv_vle32_v_i32m1(B_col, vl);
30	            vint32m1_t vc = __riscv_vmul_vv_i32m1(va, vb, vl);
31	            
32	            vint32m1_t vzero = __riscv_vmv_s_x_i32m1(0, vl);
33	            vint32m1_t vsum = __riscv_vredsum_vs_i32m1_i32m1(vc, vzero, vl);
34	            C[i][j] = __riscv_vmv_x_s_i32m1_i32(vsum);
35	        }
36	    }
37	}
