39	void print_matrix(int32_t mat[N][N], const char* name) {
40	    printf("%s:\n", name);
41	    for (int i = 0; i < N; i++) {
42	        for (int j = 0; j < N; j++) {
43	            printf("%6d ", mat[i][j]);
44	        }
45	        printf("\n");
46	    }
47	    printf("\n");
48	}
