51	    for (int i = 0; i < N; i++) {
52	        for (int j = 0; j < N; j++) {
53	            if (C1[i][j] != C2[i][j]) {
54	                printf("Mismatch at [%d][%d]: scalar=%d, rvv=%d\n", 
55	                       i, j, C1[i][j], C2[i][j]);
56	                return 0;
57	            }
58	        }
59	    }
60	    return 1;
61	}
