// in this demo, you should 0, 1, 2 in the first run
// and see 3, 4 after resume

#include <stdio.h>
#include "platform.h"

int main(void) {

	/* Disable interrupts in general. */
	clear_csr(NDS_MSTATUS, MSTATUS_MIE);

	/* Enable interrupt bit in mie to allow interrupt to wake up WFI mode */
	set_csr(NDS_MIE, MIP_MEIP | MIP_MTIP | MIP_MSIP);

  // set IRQ_SOURCE = 1 to highest priority, and enable it in PLIC
  __nds__plic_set_priority(1, 255);
  __nds__plic_enable_interrupt(1);
  __nds__plic_set_threshold(0);

  volatile int data[5];
  for (int i = 0; i < 5; ++i) {
    data[i] = i;
    if (i == 3) {
      __asm__ volatile("wfi");
      // if you run vsim with --save, simulation will exit here, and
      // a snapshot is saved.
      // if you run vsim with --resume, simulation will resume from
      // here from the snapshot
    }
    printf("%d, %d\n", i, data[i]);
  }
  return 0;
}

