#include <stdio.h>

int total = 0;

int main(void)
{
    unsigned long hartid;
    __asm__("csrr %0, mhartid" : "=r"(hartid));

    static _Bool flag = 0;

    while (__atomic_test_and_set(&flag, __ATOMIC_SEQ_CST));
    // critical section
    printf("hello world from hart %lu!\n", hartid);
    total += 1;
    __atomic_clear(&flag, __ATOMIC_SEQ_CST);

    // Read from SMU.SYSTEMCFG
    const unsigned int core_num = (*(unsigned int*)(0xf0100008)) & 0xFF;

    // Wait until all threads have finished the critical section
    while(__atomic_load_n(&total, __ATOMIC_SEQ_CST) < core_num) {
        // Optionally add a pause/yield instruction to reduce contention
        __asm__ __volatile__("" ::: "memory");
    }

    return 0;
}

