#include <inttypes.h>
#include <stdio.h>
#include <stdlib.h>

#include "core_v5.h"
#include "interrupt.h"

#define skip printf

volatile unsigned long test_start_addr;
unsigned long isz;
unsigned long dsz;

void ecall_handler() {

	unsigned long micm_cfg	= read_csr(NDS_MICM_CFG);
	unsigned long mdcm_cfg	= read_csr(NDS_MDCM_CFG);
		      isz	= ((micm_cfg >> 6) & 0x7);  //icache line size
		      dsz	= ((mdcm_cfg >> 6) & 0x7);

	unsigned long ilmsz	= ((micm_cfg >> 15) & 0x1f);
	unsigned long dlmsz	= ((mdcm_cfg >> 15) & 0x1f);
	unsigned long ilmszk	= 1<<(((micm_cfg >> 15) & 0x1f)+ 9);
	unsigned long dlmszk	= 1<<(((mdcm_cfg >> 15) & 0x1f)+ 9);

	// Ignore  testing in case of no Icache or Dcache
	if ((isz == 0) && (dsz == 0)) {
                skip("NDS_ICACHE_SUPPORT=no and NDS_DCACHE_SUPPORT=no\n");
	}

	// Turn on Icache and Dcache
	if (isz != 0) {
		set_csr(NDS_MCACHE_CTL,1);
	}
	if (dsz != 0) {
		set_csr(NDS_MCACHE_CTL,2);
	}

	unsigned long milmb, ibpa, ilm_addr;
	unsigned long mdlmb, dbpa, dlm_addr;
	milmb = 0; ibpa = 0; ilm_addr = 0;
	mdlmb = 0; dbpa = 0; dlm_addr = 0;
	unsigned long *ptr;	
	asm volatile("la %0, test_jump" : "=r"(ptr));
	test_start_addr = (unsigned long) ptr;

	if(ilmsz !=0 ){
		milmb	= read_csr(NDS_MILMB);
		ibpa	= (milmb >> 10) << 10;		//base physical address of ILM
		ilm_addr = ibpa + ilmszk;
	}
	if(dlmsz != 0){
		mdlmb	= read_csr(NDS_MDLMB);
		dbpa	= (mdlmb >> 10) << 10;
		dlm_addr = dbpa + dlmszk;
	}

	if (ibpa <= test_start_addr && test_start_addr < ilm_addr) {
		test_start_addr = ilm_addr;
		if (dbpa <= test_start_addr && test_start_addr < dlm_addr) {
			test_start_addr = dlm_addr;
		}
	} else {
		if (dbpa <= test_start_addr &&  test_start_addr < dlm_addr) {
			test_start_addr = dlm_addr;
		}
	}
}

int main (int argc, char** argv) {

    ecall_handler();

	int i, j;
	unsigned long offset;

	unsigned long data_pat    = 0xf1f11ff1;
	unsigned long data_1;
	unsigned long data_2;

	unsigned long ret_insn    = 0x00008067;// jr ra
	unsigned long abort_insn  = 0x00000000;// illegal instrution
	unsigned long *ptr;

	// Save RA
	volatile int save_ra;
	asm volatile("mv %0, ra" : "=r"(save_ra));

	// Test D-Cache
	if (dsz != 0) {
		offset	= (8*1024/8);
		ptr 	= (unsigned long*) test_start_addr;
		data_1  = *ptr;
		ptr    -= offset;

	// Store data
		for(i = 0;i < 8; i++) {
			ptr    += offset;
			data_1 += data_pat;
			*ptr    = data_1;
		}
	// Check data
		ptr 	= (unsigned long*)test_start_addr;
		data_2  = *ptr;
		ptr    -= offset;
		for(i = 0;i < 8; i++) {
			ptr    += offset;
			data_1  = *ptr;
			if((data_1 ^ data_2) != 0) {
				exit(7);
			}
			data_2 += data_pat;
		}
	}
	// Test I-Cache
	if (isz != 0) {
	// Store instruction
		offset	= (8*1024/8);
		ptr 	= (unsigned long*)test_start_addr;
		ptr    -= offset;
		for(i = 0;i < 8; i++) {
			ptr    += offset;
			*ptr = ret_insn;
        	        for(j = 0;j < 8; j++) {
                	        ptr += 1;
                        	*ptr = abort_insn;
	                }
			ptr = (ptr - 8);
		}
		asm volatile ("fence.i");	// Write-back all data in caches

	// Load instruction
		ptr 	= (unsigned long*)test_start_addr;
		ptr    -= offset;
		for(i = 0;i < 8; i++) {
			ptr += offset;
			asm volatile ("jalr %0" :: "r"(ptr));
		}
	}
	asm volatile("j test_jump_end");
	asm volatile(".align 3");
	asm volatile("test_jump:");
	asm volatile(".fill 16384, 4, 0x00000000");
	asm volatile("test_jump_end:");

	// Restore RA
	asm volatile("mv ra, %0" : "=r"(save_ra));

    return 0;
}

