/*
 * calc_cycle.h
 *
 *  Created on: Mar 14, 2022
 *      Author: yuqiliu
 */

#ifndef CALC_CYCLE_H_
#define CALC_CYCLE_H_
#include <stdint.h>

extern uint64_t cycle;
extern uint64_t cycleStart;

#define StartCalc cycleStart = get_sim_clock();
#define EndCalc cycle = get_sim_clock() - cycleStart;

static inline __attribute__((always_inline)) unsigned long long
get_sim_clock(void)
{
  unsigned long long cycle;
/* Get the cycle count from $pfr0. */
#if __riscv_xlen == 64
  __asm volatile("csrrs %0, mcycle, zero" : "=r"(cycle));
#elif __riscv_xlen == 32
  unsigned low_part, high_part, tmp;

  __asm volatile("1:\n"
                 " csrrs %0, mcycleh, zero\n"
                 " csrrs %1, mcycle, zero\n"
                 " csrrs %2, mcycleh, zero\n"
                 " bne %2, %0, 1b\n"
                 : "=r"(high_part), "=r"(low_part), "=r"(tmp));
  cycle = high_part;
  cycle <<= 32;
  cycle |= low_part;
#else
#error Unknwon __riscv_xlen
#endif

  return cycle;
}

#endif /* CALC_CYCLE_H_ */

