6	/*
7	 * This demo program shows how to active machine and PLIC related interrupts.
8	 * It enables machine mtime, machine software, PLIC PIT interrupts.
9	 *
10	 * The Machine Mtime interrupt:
11	 * The machine mtime interrupt period is set to 2 seconds. If the interrupt
12	 * happens then the handler sets the machine software trigger flag.
13	 *
14	 * The PLIC PIT interrupt:
15	 * The PLIC PIT interrupt period is set to 200 milliseconds. If the interrupt
16	 * happens then the handler sets the machine software trigger flag.
17	 *
18	 * The Machine Software interrupt:
19	 * The machine software interrupt is actived when machine software trigger flag
20	 * is set by machine mtime interrupt or PLIC PIT interrupt.
21	 * It will output UART message to show machine mtime or PLIC PIT is alive.
22	 *
23	 * The main function:
24	 * The main function checks the flag status changed by machine mtime or PLIC PIT
25	 * interrupt to trigger the machine software interrupt.
26	 *
27	 * Scenario:
28	 *
29	 * The machine software interrupt is actived to output machine mtime is alive message
30	 * every 2 seconds by setting the trigger flag from machine mtime interrupt handler.
31	 * And the PLIC SWINT interrupt is actived to output PLIC PIT is alive message every
32	 * 200ms by setting the trigger flag from PLIC PIT interrupt handler.
33	 *
34	 */
35	#include <stdio.h>
36	//#include "config.h"
37	#include "platform.h"
38	
39	#define MACHINE_TIMER_PERIOD            15000
40	#define PIT_TIMER_PERIOD                10000
41	
42	/* The flag to trigger Machine software interrupt */
43	static volatile char trigger_mswi_flag = 0;
44	
45	/* The flag to trigger UART output message */
46	static volatile char trigger_mswi_uart_msg_flag = 0;
47	
48	/* The flag to trigger UART output message */
49	static volatile char trigger_pit_uart_msg_flag = 0;
50	
51	void  __attribute__((used, noinline))  wait_in_wfi() {
52	  asm volatile("1: wfi\n\t"
53	               "j 1b" ::: "memory");
54	}
55	
56	#ifdef CFG_GCOV
57	/*
58	 * Since this is an endless program, we use GPIO key
59	 * to terminate the program to perform GCOV scenario.
60	 */
61	
62	#include <stdlib.h>
63	
64	void gpio_irq_handler(void)
65	{
66		/* Clear GPIO interrupt status */
67		gpio_irq_clear(0xFFFFFFFF);
68	
69		printf("Terminate program by GPIO key!\n");
70	
71		/* Terminate program */
72		exit(1);
73	}
74	
75	void setup_gpio(void)
76	{
77		/* Initial GPIO key */
78		gpio_init(GPIO_USED_MASK);
79	
80		/* Priority must be set > 0 to trigger the interrupt */
81		HAL_INTERRUPT_SET_LEVEL(IRQ_GPIO_SOURCE, 1);
82	
83		/* Enable PLIC interrupt GPIO source */
84		HAL_INTERRUPT_ENABLE(IRQ_GPIO_SOURCE);
85	}
86	#endif
