88	__attribute__((always_inline))
89	static inline unsigned long long rdmtime(void)
90	{
91	#if __riscv_xlen == 32
92		do {
93			unsigned long hi = ((volatile unsigned long *)&DEV_PLMT->MTIME)[1];
94			unsigned long lo = ((volatile unsigned long *)&DEV_PLMT->MTIME)[0];
95			/* Return if no overflow */
96			if (hi == ((volatile unsigned long *)&DEV_PLMT->MTIME)[1])
97				return ((unsigned long long)hi << 32) | lo;
98		} while(1);
99	#else
100		return DEV_PLMT->MTIME;
101	#endif
102	}
103	
104	__attribute__((always_inline))
105	static inline void wmtimecmp(unsigned long long val)
106	{
107	#if __riscv_xlen == 32
108		/* No smaller than old value */
109		((volatile unsigned long *)&DEV_PLMT->MTIMECMP)[0] = -1;
110		((volatile unsigned long *)&DEV_PLMT->MTIMECMP)[1] = val >> 32;
111		/* Set new value */
112		((volatile unsigned long *)&DEV_PLMT->MTIMECMP)[0] = (val << 32) >> 32;
113	#else
114		DEV_PLMT->MTIMECMP = val;
115	#endif
116	}
117	
118	void mtime_handler(void)
119	{
120		/* Reset the timer to specified period */
121		wmtimecmp(rdmtime() + MACHINE_TIMER_PERIOD);
122	
123		/*
124		 * Set the flag to trigger Machine software interrupt.
125		 * The Machine SWI interrupt handler will output message to indicate
126		 * Machine mtime is alive.
127		 */
128		trigger_mswi_flag = 1;
129		trigger_mswi_uart_msg_flag = 1;
130	}
131	
132	void mswi_handler(void)
133	{
134		HAL_MSWI_CLEAR();
135	
136		/*
137		 * It is triggered by Machine mtime interrupt handler.
138		 * Output messgaes to indicate Machine mtime is alive.
139		 */
140		if(trigger_mswi_uart_msg_flag) {
141			/* Clear UART output message trigger flag */
142			trigger_mswi_uart_msg_flag = 0;
143	
144			printf("Message triggered from machine time interrupt\n");
145		}
146	
147		/*
148		 * It is triggered by PIT interrupt handler.
149		 * Output messgaes to indicate PLIC PIT is alive.
150		 */
151		if(trigger_pit_uart_msg_flag) {
152			/* Clear UART output message trigger flag */
153		 	trigger_pit_uart_msg_flag = 0;
154	
155			printf("Message triggered from PLIC PIT interrupt\n");
156		}
157	}
158	
159	void pit_irq_handler(void)
160	{
161		/* Clear PIT interrupt status */
162		pit_irq_clear(0);
163	
164		/*
165		 * Set the flag to trigger Machine software interrupt.
166		 * The Machine SWI interrupt handler will output message to indicate
167		 * the PLIC PIT is alive.
168		 */
169		trigger_mswi_flag = 1;
170		trigger_pit_uart_msg_flag = 1;
171	}
172	
173	void setup_mtimer(void)
174	{
175		HAL_MTIMER_INITIAL();
176	
177		/* Active machine timer */
