 *
 */
/*
 * This demo program shows how to active machine and PLIC related interrupts.
 * It enables machine mtime, machine software, PLIC PIT interrupts.
 *
 * The Machine Mtime interrupt:
 * The machine mtime interrupt period is set to 2 seconds. If the interrupt
 * happens then the handler sets the machine software trigger flag.
 *
 * The PLIC PIT interrupt:
 * The PLIC PIT interrupt period is set to 200 milliseconds. If the interrupt
 * happens then the handler sets the machine software trigger flag.
 *
 * The Machine Software interrupt:
 * The machine software interrupt is actived when machine software trigger flag
 * is set by machine mtime interrupt or PLIC PIT interrupt.
 * It will output UART message to show machine mtime or PLIC PIT is alive.
 *
 * The main function:
 * The main function checks the flag status changed by machine mtime or PLIC PIT
 * interrupt to trigger the machine software interrupt.
 *
 * Scenario:
 *
 * The machine software interrupt is actived to output machine mtime is alive message
 * every 2 seconds by setting the trigger flag from machine mtime interrupt handler.
 * And the PLIC SWINT interrupt is actived to output PLIC PIT is alive message every
 * 200ms by setting the trigger flag from PLIC PIT interrupt handler.
 *
 */
#include <stdio.h>
//#include "config.h"
#include "platform.h"

#define MACHINE_TIMER_PERIOD            15000
#define PIT_TIMER_PERIOD                10000

/* The flag to trigger Machine software interrupt */
static volatile char trigger_mswi_flag = 0;

/* The flag to trigger UART output message */
static volatile char trigger_mswi_uart_msg_flag = 0;

/* The flag to trigger UART output message */
static volatile char trigger_pit_uart_msg_flag = 0;

void  __attribute__((used, noinline))  wait_in_wfi() {
  asm volatile("1: wfi\n\t"
               "j 1b" ::: "memory");
}

#ifdef CFG_GCOV
/*
 * Since this is an endless program, we use GPIO key
 * to terminate the program to perform GCOV scenario.
 */

#include <stdlib.h>

void gpio_irq_handler(void)
{
	/* Clear GPIO interrupt status */
	gpio_irq_clear(0xFFFFFFFF);

	printf("Terminate program by GPIO key!\n");

	/* Terminate program */
	exit(1);
}

void setup_gpio(void)
{
	/* Initial GPIO key */
	gpio_init(GPIO_USED_MASK);

	/* Priority must be set > 0 to trigger the interrupt */
	HAL_INTERRUPT_SET_LEVEL(IRQ_GPIO_SOURCE, 1);

	/* Enable PLIC interrupt GPIO source */
	HAL_INTERRUPT_ENABLE(IRQ_GPIO_SOURCE);
}
#endif

__attribute__((always_inline))
static inline unsigned long long rdmtime(void)
{
#if __riscv_xlen == 32
	do {
		unsigned long hi = ((volatile unsigned long *)&DEV_PLMT->MTIME)[1];
		unsigned long lo = ((volatile unsigned long *)&DEV_PLMT->MTIME)[0];
		/* Return if no overflow */
		if (hi == ((volatile unsigned long *)&DEV_PLMT->MTIME)[1])
			return ((unsigned long long)hi << 32) | lo;
	} while(1);
#else
	return DEV_PLMT->MTIME;
#endif
}

__attribute__((always_inline))
static inline void wmtimecmp(unsigned long long val)
{
#if __riscv_xlen == 32
	/* No smaller than old value */
	((volatile unsigned long *)&DEV_PLMT->MTIMECMP)[0] = -1;
	((volatile unsigned long *)&DEV_PLMT->MTIMECMP)[1] = val >> 32;
	/* Set new value */
	((volatile unsigned long *)&DEV_PLMT->MTIMECMP)[0] = (val << 32) >> 32;
#else
	DEV_PLMT->MTIMECMP = val;
#endif
}

void mtime_handler(void)
{
	/* Reset the timer to specified period */
	wmtimecmp(rdmtime() + MACHINE_TIMER_PERIOD);

	/*
	 * Set the flag to trigger Machine software interrupt.
	 * The Machine SWI interrupt handler will output message to indicate
	 * Machine mtime is alive.
	 */
	trigger_mswi_flag = 1;
	trigger_mswi_uart_msg_flag = 1;
}

void mswi_handler(void)
{
	HAL_MSWI_CLEAR();

	/*
	 * It is triggered by Machine mtime interrupt handler.
	 * Output messgaes to indicate Machine mtime is alive.
	 */
	if(trigger_mswi_uart_msg_flag) {
		/* Clear UART output message trigger flag */
		trigger_mswi_uart_msg_flag = 0;

		printf("Message triggered from machine time interrupt\n");
	}

	/*
	 * It is triggered by PIT interrupt handler.
	 * Output messgaes to indicate PLIC PIT is alive.
	 */
	if(trigger_pit_uart_msg_flag) {
		/* Clear UART output message trigger flag */
	 	trigger_pit_uart_msg_flag = 0;

		printf("Message triggered from PLIC PIT interrupt\n");
	}
}

void pit_irq_handler(void)
{
	/* Clear PIT interrupt status */
	pit_irq_clear(0);

	/*
	 * Set the flag to trigger Machine software interrupt.
	 * The Machine SWI interrupt handler will output message to indicate
	 * the PLIC PIT is alive.
	 */
	trigger_mswi_flag = 1;
	trigger_pit_uart_msg_flag = 1;
}

void setup_mtimer(void)
{
	HAL_MTIMER_INITIAL();

	/* Active machine timer */
	wmtimecmp(rdmtime() + MACHINE_TIMER_PERIOD);

	HAL_MTIME_ENABLE();
}

void setup_mswi(void)
{
	HAL_MSWI_INITIAL();
	HAL_MSWI_ENABLE();
}

void setup_pit_timer(unsigned int period)
{
	/* Setup system PIT timer */
	pit_init();
	pit_set_period(0, period);
	pit_irq_enable(0);

	/* Priority level must be set > 0 to trigger the interrupt */
	HAL_INTERRUPT_SET_LEVEL(IRQ_PIT_SOURCE, 1);

	/* Enable PLIC interrupt PIT source */
	HAL_INTERRUPT_ENABLE(IRQ_PIT_SOURCE);

	/* Start PIT timer */
	pit_start(0);
}

void trigger_mswi(void)
{
	/* Trigger Machine software interrupt */
	HAL_MSWI_PENDING();
}

int main(void)
{
	printf("\nAndes V5 demo-plic program\n");

	/* Disable the Machine external, timer and software interrupts until setup is done */
	clear_csr(NDS_MIE, MIP_MEIP | MIP_MTIP | MIP_MSIP);

#ifdef CFG_GCOV
	/* Terminate program to perform GCOV by GPIO key. */
	setup_gpio();
#endif


	setup_mswi();

	/* Setup Machine mtime and software interrupt */
	setup_mtimer();

	/* Setup PLIC PIT interrupt */
	setup_pit_timer(PIT_TIMER_PERIOD);

	/* Enable the Machine External/Timer/Sofware interrupt bit in MIE. */
	set_csr(NDS_MIE, MIP_MEIP | MIP_MTIP | MIP_MSIP);

	/* This is for hybrid simulation (QEMU+VSIM) demo, notice that
		it has to be called when interrupts are disabled, i.e. mstatus.mie = 0
	*/
	// wait_in_wfi();

	/* Enable interrupts in general. */
	set_csr(NDS_MSTATUS, MSTATUS_MIE);

	/*
	 * Check the flags to trigger Machine software interrupt to
	 * output messages to indicate the system is alive.
	 */
	for (int i = 0; i < 20000; i++) {
		if(trigger_mswi_flag) {
			/* Clear Machine software trigger flag */
			trigger_mswi_flag = 0;

			trigger_mswi();
		}
	}

	return 0;
}

