#include <inttypes.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdarg.h>

#include "core_v5.h"
#include "interrupt.h"

// Shared data array for cache testing
#define ARRAY_SIZE 1024
#define CACHE_LINE_SIZE 64
#define NUM_ITERATIONS 100

#if __riscv_xlen == 64
#define CACHE_TAG_SHIFT 32
#else
#define CACHE_TAG_SHIFT 16
#endif

// Volatile to prevent compiler optimizations
volatile unsigned long shared_data[ARRAY_SIZE] __attribute__((aligned(CACHE_LINE_SIZE)));
volatile int barrier_counter = 0;
volatile int barrier_sense = 0;  // For sense-reversal barrier
volatile _Bool printf_lock = 0;

// Thread-safe printf wrapper using spinlock because newlib not support reentrant yet
static inline void safe_printf(const char *format, ...) {
    // Acquire lock
    while (__atomic_test_and_set(&printf_lock, __ATOMIC_SEQ_CST))
        __asm__ __volatile__("" ::: "memory");

    // Print (need to use va_list for variadic arguments)
    va_list args;
    va_start(args, format);
    vprintf(format, args);
    va_end(args);

    // Release lock
    __atomic_clear(&printf_lock, __ATOMIC_SEQ_CST);
}

#define printf safe_printf
//#define printf

// TODO: consider giving each thread its own local sense?
// see https://github.com/leiyucs/Barrier-Synchronization/blob/master/sensereversal_openmp.c
// Reusable barrier implementation using sense-reversal technique
void barrier_sync(int num_cores) {
    int local_sense = __atomic_load_n(&barrier_sense, __ATOMIC_SEQ_CST);
    int arrived = __atomic_fetch_add(&barrier_counter, 1, __ATOMIC_SEQ_CST) + 1;

    if (arrived == num_cores) {
        // Last core to arrive resets the counter and flips the sense
        __atomic_store_n(&barrier_counter, 0, __ATOMIC_SEQ_CST);
        __atomic_store_n(&barrier_sense, !local_sense, __ATOMIC_SEQ_CST);
    } else {
        // Wait for sense to flip
        while(__atomic_load_n(&barrier_sense, __ATOMIC_SEQ_CST) == local_sense) {
            __asm__ __volatile__("" ::: "memory");
        }
    }
}

// Test 1: Cache coherence test - one core writes, others read
int test_cache_coherence(unsigned long hartid, int num_cores) {
    int errors = 0;

    // Initialize shared data (only hart 0)
    if (hartid == 0) {
        for (int i = 0; i < ARRAY_SIZE; i++) {
            shared_data[i] = 0;
        }
        printf("[Hart %lu] Initialized shared data\n", hartid);
    }

    barrier_sync(num_cores);

    // Hart 0 writes pattern
    if (hartid == 0) {
        printf("[Hart %lu] Writing pattern to shared data...\n", hartid);
        for (int i = 0; i < ARRAY_SIZE; i++) {
            shared_data[i] = 0xDEADBEEF00000000UL | i;
        }
        __sync_synchronize(); // Memory barrier
        printf("[Hart %lu] Write complete\n", hartid);
    }

    barrier_sync(num_cores);

    // All harts read and verify
    printf("[Hart %lu] Reading and verifying shared data...\n", hartid);
    for (int i = 0; i < ARRAY_SIZE; i++) {
        unsigned long expected = 0xDEADBEEF00000000UL | i;
        unsigned long actual = shared_data[i];
        if (actual != expected) {
            printf("[Hart %lu] ERROR at index %d: expected 0x%lx, got 0x%lx\n",
                   hartid, i, expected, actual);
            errors++;
            if (errors > 10) break; // Limit error output
        }
    }

    if (errors == 0) {
        printf("[Hart %lu] Cache coherence test PASSED\n", hartid);
    } else {
        printf("[Hart %lu] Cache coherence test FAILED with %d errors\n", hartid, errors);
    }

    barrier_sync(num_cores);
    return errors;
}

// Test 2: Ping-pong test - alternating writes between cores
int test_cache_ping_pong(unsigned long hartid, int num_cores) {
    int errors = 0;
    volatile unsigned long *ping_pong = &shared_data[0];

    if (hartid == 0) {
        printf("[Hart %lu] Starting ping-pong test...\n", hartid);
        *ping_pong = 0;
    }

    barrier_sync(num_cores);

    // Each hart increments the counter in turn
    for (int iter = 0; iter < NUM_ITERATIONS; iter++) {
        int target_hart = iter % num_cores;

        if (hartid == target_hart) {
            // Wait for the correct value
            unsigned long expected = iter;
            unsigned long actual;
            int timeout = 1000000;
            do {
                actual = __atomic_load_n(ping_pong, __ATOMIC_SEQ_CST);
                timeout--;
                if (timeout == 0) {
                    printf("[Hart %lu] TIMEOUT at iteration %d: expected %lu, got %lu\n",
                           hartid, iter, expected, actual);
                    errors++;
                    goto ping_pong_end;
                }
            } while (actual != expected);

            // Increment
            __atomic_store_n(ping_pong, actual + 1, __ATOMIC_SEQ_CST);
        }
    }

ping_pong_end:
    barrier_sync(num_cores);

    if (errors == 0 && hartid == 0) {
        printf("[Hart %lu] Ping-pong test PASSED (final value: %lu)\n", hartid, *ping_pong);
    } else if (errors > 0) {
        printf("[Hart %lu] Ping-pong test FAILED with %d errors\n", hartid, errors);
    }

    return errors;
}

// Test 3: Parallel write test - all cores write to different cache lines
int test_parallel_write(unsigned long hartid, int num_cores) {
    int errors = 0;

    // Clear data
    if (hartid == 0) {
        printf("[Hart %lu] Starting parallel write test...\n", hartid);
        for (int i = 0; i < ARRAY_SIZE; i++) {
            shared_data[i] = 0;
        }
    }

    barrier_sync(num_cores);

    // Each hart writes to its own section
    int section_size = ARRAY_SIZE / num_cores;
    int start = hartid * section_size;
    int end = start + section_size;

    printf("[Hart %lu] Writing to indices %d-%d\n", hartid, start, end-1);
    for (int i = start; i < end; i++) {
        shared_data[i] = ((unsigned long)hartid << CACHE_TAG_SHIFT) | (unsigned long)i;
    }

    __sync_synchronize();
    barrier_sync(num_cores);

    // Verify all data
    printf("[Hart %lu] Verifying all data...\n", hartid);
    for (int core = 0; core < num_cores; core++) {
        start = core * section_size;
        end = start + section_size;
        for (int i = start; i < end; i++) {
            unsigned long expected = ((unsigned long)core << CACHE_TAG_SHIFT) | (unsigned long)i;
            unsigned long actual = shared_data[i];
            if (actual != expected) {
                printf("[Hart %lu] ERROR: index %d written by core %d: expected 0x%lx, got 0x%lx\n",
                       hartid, i, core, expected, actual);
                errors++;
                if (errors > 10) goto parallel_end;
            }
        }
    }

parallel_end:
    if (errors == 0) {
        printf("[Hart %lu] Parallel write test PASSED\n", hartid);
    } else {
        printf("[Hart %lu] Parallel write test FAILED with %d errors\n", hartid, errors);
    }

    barrier_sync(num_cores);
    return errors;
}

// Test 4: Concurrent atomic increment - all cores increment the same counter
int test_concurrent_increment(unsigned long hartid, int num_cores) {
    int errors = 0;
    volatile unsigned long *counter = &shared_data[0];

    if (hartid == 0) {
        *counter = 0;
        printf("[Hart %lu] Starting concurrent increment test...\n", hartid);
    }

    barrier_sync(num_cores);

    // All harts increment the same counter NUM_ITERATIONS times
    printf("[Hart %lu] Performing %d atomic increments...\n", hartid, NUM_ITERATIONS);
    for (int i = 0; i < NUM_ITERATIONS; i++) {
        __atomic_fetch_add(counter, 1, __ATOMIC_SEQ_CST);
    }

    barrier_sync(num_cores);

    // Check final value (only hart 0 reports)
    if (hartid == 0) {
        unsigned long final_value = __atomic_load_n(counter, __ATOMIC_SEQ_CST);
        unsigned long expected = (unsigned long)num_cores * NUM_ITERATIONS;

        printf("[Hart %lu] Final counter value: %lu, expected: %lu\n",
               hartid, final_value, expected);

        if (final_value == expected) {
            printf("[Hart %lu] Concurrent increment test PASSED\n", hartid);
        } else {
            printf("[Hart %lu] Concurrent increment test FAILED: lost %lu updates\n",
                   hartid, expected - final_value);
            errors = 1;
        }
    }

    barrier_sync(num_cores);
    return errors;
}

// Check if shared cache exists via SMU
int check_shared_cache() {
    // Read from SMU.SYSTEMCFG (offset 0x08)
    const unsigned int system_cfg = *(unsigned int*)(0xf0100008);
    const unsigned int has_shared_cache = (system_cfg >> 8) & 0x1;

    return has_shared_cache;
}

int main(void) {
    unsigned long hartid;
    __asm__("csrr %0, mhartid" : "=r"(hartid));

    // Read core configuration from SMU
    const unsigned int system_cfg = *(unsigned int*)(0xf0100008);
    const int num_cores = system_cfg & 0xFF;
    const int has_shared_cache = (system_cfg >> 8) & 0x1;

    if (hartid == 0) {
        printf("\n========================================\n");
        printf("Multi-Core Shared Cache Test\n");
        printf("========================================\n");
        printf("Number of cores: %d\n", num_cores);
        printf("Shared cache present: %s\n", has_shared_cache ? "YES" : "NO");
        printf("Array size: %d elements\n", ARRAY_SIZE);
        printf("Cache line size: %d bytes\n", CACHE_LINE_SIZE);
        printf("========================================\n\n");

        if (!has_shared_cache) {
            printf("WARNING: No shared cache detected. Tests may not behave as expected.\n\n");
        }
    }

    // Synchronize all cores before starting tests
    barrier_sync(num_cores);

    // Test 1: Cache Coherence
    if (hartid == 0) {
        printf("\n--- Test 1: Cache Coherence ---\n");
    }
    barrier_sync(num_cores);
    if (test_cache_coherence(hartid, num_cores) != 0)
        exit(1);

    // Test 2: Ping-Pong
    if (hartid == 0) {
        printf("\n--- Test 2: Cache Ping-Pong ---\n");
    }
    barrier_sync(num_cores);
    if (test_cache_ping_pong(hartid, num_cores) != 0)
        exit(2);

    // Test 3: Parallel Write
    if (hartid == 0) {
        printf("\n--- Test 3: Parallel Write ---\n");
    }
    barrier_sync(num_cores);
    if (test_parallel_write(hartid, num_cores) != 0)
        exit(3);

    // Test 4: Concurrent Increment
    if (hartid == 0) {
        printf("\n--- Test 4: Concurrent Atomic Increment ---\n");
    }
    barrier_sync(num_cores);
    if (test_concurrent_increment(hartid, num_cores) != 0)
        exit(4);

    // All tests passed
    barrier_sync(num_cores);
    if (hartid == 0) {
        printf("\n========================================\n");
        printf("ALL TESTS PASSED\n");
        printf("========================================\n");
    }

    return 0;
}

