		unsigned csr_vtype_vsew = (csr_vtype >> 3) & 0x7;
    int32_t signed_rs1 = rs1;
    switch (csr_vtype_vsew) {
			case 0: {
				vd.u8[0] = abs(vs2.i8[0] - signed_rs1);
				vd.u8[1] = abs(vs2.i8[1] - signed_rs1);
				vd.u8[2] = abs(vs2.i8[2] - signed_rs1);
				vd.u8[3] = abs(vs2.i8[3] - signed_rs1);
				break;
			}
			case 1: {
